using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.WebUtilities;
using System.Text;
public static class ActivationTokens
{
public static string Create(IDataProtector protector, string userId, DateTimeOffset expiresUtc)
{
var payload = $"{userId}|{expiresUtc.UtcDateTime:o}";
var protectedBytes = protector.Protect(Encoding.UTF8.GetBytes(payload));
return WebEncoders.Base64UrlEncode(protectedBytes);
}
public static bool TryValidate(IDataProtector protector, string token, out string userId)
{
userId = "";
byte[] protectedBytes;
try { protectedBytes = WebEncoders.Base64UrlDecode(token); }
catch { return false; }
byte[] bytes;
try { bytes = protector.Unprotect(protectedBytes); }
catch { return false; } // tampered / wrong key / etc.
var payload = Encoding.UTF8.GetString(bytes);
var parts = payload.Split('|');
if (parts.Length != 2) return false;
userId = parts[0];
if (!DateTimeOffset.TryParse(parts[1], out var exp)) return false;
return exp > DateTimeOffset.UtcNow;
}
}

using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.WebUtilities;
using System.Text;
app.MapPost("/register", async (
UserManager<AppUser> userManager,
IEmailSender emailSender,
HttpContext http,
RegisterRequest req) =>
{
var user = new AppUser { UserName = req.Email, Email = req.Email };
var result = await userManager.CreateAsync(user, req.Password);
if (!result.Succeeded) return Results.BadRequest(result.Errors);
var token = await userManager.GenerateEmailConfirmationTokenAsync(user);
// Token contains characters that should be URL-encoded safely:
var tokenEncoded = WebEncoders.Base64UrlEncode(Encoding.UTF8.GetBytes(token));
var link = $"{http.Request.Scheme}://{http.Request.Host}/confirm-email?userId={user.Id}&token={tokenEncoded}";
await emailSender.SendEmailAsync(req.Email, "Confirm your account",
$"Click to confirm: {link}");
return Results.Ok("Check your email to activate your account.");
});
record RegisterRequest(string Email, string Password);

app.MapPost("/register-custom", async (AppDbContext db, IDataProtector protector, HttpContext http, RegisterRequest req) =>
{
var user = new UserAccount { Id = Guid.NewGuid().ToString(), Email = req.Email, EmailConfirmed = false };
// set PasswordHash using PasswordHasher or your KDF...
db.Users.Add(user);
await db.SaveChangesAsync();
var token = ActivationTokens.Create(protector, user.Id, DateTimeOffset.UtcNow.AddHours(24));
var link = $"{http.Request.Scheme}://{http.Request.Host}/activate?token={token}";
// send email with link...
return Results.Ok("Check your email to activate.");
});

using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.WebUtilities;
using System.Text;
app.MapGet("/confirm-email", async (
UserManager<AppUser> userManager,
string userId,
string token) =>
{
var user = await userManager.FindByIdAsync(userId);
if (user is null) return Results.NotFound();
// Decode from Base64Url back into the original token string
var tokenDecoded = Encoding.UTF8.GetString(WebEncoders.Base64UrlDecode(token));
var result = await userManager.ConfirmEmailAsync(user, tokenDecoded);
if (!result.Succeeded) return Results.BadRequest(result.Errors);
return Results.Ok("Email confirmed. You can log in now.");
});
